def calculate_W_partition(n, partition):
    edges_in_cliques = [s * (s - 1) // 2 for s in partition]
    E = sum(edges_in_cliques)
    W = 0
    for i in range(len(partition)):
        s_i = partition[i]
        e_i = edges_in_cliques[i]
        if e_i == 0: continue
        term1 = (n - s_i) * (n - s_i - 1) // 2
        term2 = E - e_i
        W += e_i * (term1 - term2)
    return W

def partitions(n):
    def backtrack(remaining, min_val):
        if remaining == 0:
            yield []
            return
        for i in range(min_val, remaining + 1):
            for p in backtrack(remaining - i, i):
                yield [i] + p
    return backtrack(n, 1)

